        <Item
          key={item.id}
          id={item.id}
          name={item.name}
          price={item.price}
          quantity={item.quantity}
          onRemove={() => handleRemoveItem(item.id)}
        />
      ))}
      <p>Total: ${totalPrice}</p>
      <button onClick={() => dispatch(addItem({ id: 4, name: 'New Item', price: 10.99 }))}>
